// =============================================================================
// StockStudio Pro — Prepare Windows Native Messaging Host Bundle
//
// Builds `stockstudio-nmh.exe` with static CRT linking (`-C target-feature=+crt-static`),
// validates its PE import table to guarantee zero dynamic VC++ runtime dependencies
// (`VCRUNTIME140.dll`, `VCRUNTIME140_1.dll`, `MSVCP140.dll`), stages it to Tauri's
// `externalBin` path, and writes `src-tauri/native-messaging/extension-id.nsh`.
//
// Never mutates Windows Registry during build/dev.
// =============================================================================

import { execSync } from "node:child_process"
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const repoRoot = path.resolve(__dirname, "..")
const tauriDir = path.join(repoRoot, "src-tauri")
const manifestPath = path.join(tauriDir, "Cargo.toml")
const binariesDir = path.join(tauriDir, "binaries")
const nmDir = path.join(tauriDir, "native-messaging")

const PLACEHOLDER_ID = "__STOCKSTUDIO_EXTENSION_ID_PLACEHOLDER__"
const CHROME_EXT_ID_REGEX = /^[a-p]{32}$/
const STATIC_CRT_FLAG = "-C target-feature=+crt-static"
const FORBIDDEN_DYNAMIC_CRT_DLLS = new Set([
  "vcruntime140.dll",
  "vcruntime140_1.dll",
  "msvcp140.dll",
])

/**
 * Parses the PE32 / PE32+ import directory table of a Windows executable and
 * returns the list of imported DLL names.
 */
function readPeImportedDlls(filePath) {
  const buf = readFileSync(filePath)
  if (buf.length < 0x40 || buf.subarray(0, 2).toString("ascii") !== "MZ") {
    throw new Error(`Not a valid Windows PE executable: ${filePath}`)
  }

  const peOff = buf.readUInt32LE(0x3c)
  if (buf.subarray(peOff, peOff + 4).toString("ascii") !== "PE\0\0") {
    throw new Error(`Invalid PE signature in ${filePath}`)
  }

  const numSections = buf.readUInt16LE(peOff + 6)
  const optSize = buf.readUInt16LE(peOff + 20)
  const optOff = peOff + 24
  const magic = buf.readUInt16LE(optOff)
  const importDirOff = magic === 0x20b ? optOff + 120 : optOff + 104
  const importRva = buf.readUInt32LE(importDirOff)
  const sectionsOff = optOff + optSize

  const sections = []
  for (let i = 0; i < numSections; i++) {
    const s = sectionsOff + i * 40
    sections.push({
      vaddr: buf.readUInt32LE(s + 12),
      vsize: buf.readUInt32LE(s + 8),
      rawOff: buf.readUInt32LE(s + 20),
      rawSize: buf.readUInt32LE(s + 16),
    })
  }

  const rvaToOff = (rva) => {
    for (const s of sections) {
      if (rva >= s.vaddr && rva < s.vaddr + Math.max(s.vsize, s.rawSize)) {
        return s.rawOff + (rva - s.vaddr)
      }
    }
    return -1
  }

  const dlls = []
  if (importRva === 0) return dlls

  let descOff = rvaToOff(importRva)
  while (descOff >= 0 && descOff + 20 <= buf.length) {
    const nameRva = buf.readUInt32LE(descOff + 12)
    if (nameRva === 0) break
    const nameOff = rvaToOff(nameRva)
    if (nameOff < 0) break
    let end = nameOff
    while (end < buf.length && buf[end] !== 0) end++
    dlls.push(buf.subarray(nameOff, end).toString("ascii"))
    descOff += 20
  }

  return dlls
}

function assertNoForbiddenCrtImports(exePath) {
  const imports = readPeImportedDlls(exePath)
  if (imports.length === 0) {
    throw new Error(`PE import table verification failed: no imports parsed from ${exePath}`)
  }

  const offending = imports.filter((dll) =>
    FORBIDDEN_DYNAMIC_CRT_DLLS.has(dll.trim().toLowerCase())
  )
  if (offending.length > 0) {
    throw new Error(
      `Forbidden dynamic VC++ CRT dependency detected in ${exePath}: ${offending.join(", ")}. ` +
        `All imports: [${imports.join(", ")}]`
    )
  }

  console.log(
    `[prepare-nmh-bundle] PE import check passed (${imports.length} OS imports, 0 dynamic VC++ CRT DLLs): ${imports.join(", ")}`
  )
}

const rawExtId = (process.env.STOCKSTUDIO_EXTENSION_ID ?? "").trim()
let effectiveExtId = PLACEHOLDER_ID

if (rawExtId.length > 0) {
  if (!CHROME_EXT_ID_REGEX.test(rawExtId)) {
    console.error(
      `[prepare-nmh-bundle] Invalid STOCKSTUDIO_EXTENSION_ID="${rawExtId}". ` +
        "Expected exactly 32 lowercase characters in range a-p (no wildcards)."
    )
    process.exit(1)
  }
  effectiveExtId = rawExtId
  console.log(`[prepare-nmh-bundle] Using configured Chrome Extension ID: ${effectiveExtId}`)
} else {
  console.log(
    "[prepare-nmh-bundle] STOCKSTUDIO_EXTENSION_ID not set; keeping placeholder " +
      "(NSIS installer will bundle stockstudio-nmh.exe but skip HKCU registration until ID is configured)."
  )
}

mkdirSync(nmDir, { recursive: true })
const nshContent =
  `; Auto-generated by scripts/prepare-nmh-bundle.mjs (do not store secrets here)\n` +
  `!define STOCKSTUDIO_EXTENSION_ID "${effectiveExtId}"\n`
writeFileSync(path.join(nmDir, "extension-id.nsh"), nshContent, "utf8")

if (process.platform === "win32") {
  const arch = process.arch === "arm64" ? "aarch64" : "x86_64"
  const targetTriple = `${arch}-pc-windows-msvc`

  const existingRustflags = (process.env.RUSTFLAGS ?? "").trim()
  const nmhRustflags = existingRustflags.includes("+crt-static")
    ? existingRustflags
    : [existingRustflags, STATIC_CRT_FLAG].filter(Boolean).join(" ")

  console.log(
    `[prepare-nmh-bundle] Building stockstudio-nmh.exe (${targetTriple}) with RUSTFLAGS="${nmhRustflags}"...`
  )
  execSync(
    `cargo build --release --target ${targetTriple} --manifest-path "${manifestPath}" -p stockstudio-nmh --bin stockstudio-nmh`,
    {
      cwd: repoRoot,
      stdio: "inherit",
      env: {
        ...process.env,
        RUSTFLAGS: nmhRustflags,
      },
    }
  )

  const builtExe = path.join(tauriDir, "target", targetTriple, "release", "stockstudio-nmh.exe")
  if (!existsSync(builtExe)) {
    console.error(`[prepare-nmh-bundle] Built binary not found at ${builtExe}`)
    process.exit(1)
  }

  assertNoForbiddenCrtImports(builtExe)

  mkdirSync(binariesDir, { recursive: true })
  const stagedExe = path.join(binariesDir, `stockstudio-nmh-${targetTriple}.exe`)
  copyFileSync(builtExe, stagedExe)
  assertNoForbiddenCrtImports(stagedExe)
  console.log(`[prepare-nmh-bundle] Staged verified static-CRT binary: ${stagedExe}`)
} else {
  console.log("[prepare-nmh-bundle] Non-Windows host detected; skipping Windows .exe staging.")
}
